def minimum_axis_aligned_rectangle(points):
 seen=set();best=float('inf')
 for x,y in points:
  for px,py in seen:
   if px!=x and py!=y and (px,y) in seen and (x,py) in seen:best=min(best,abs(x-px)*abs(y-py))
  seen.add((x,y))
 return 0 if best==float('inf') else best

